<?php
namespace App\Http\Controllers;
use App\Models\{Transaksi,DetailTransaksi,Stok,Pengiriman};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class CheckoutController {
 public function index(Request $r){ if(!auth()->check()) return redirect('/login')->with('error','Silakan login sebelum checkout.'); $keranjang=$r->session()->get('keranjang',[]); if(empty($keranjang)) return redirect('/keranjang'); $total=collect($keranjang)->sum(fn($i)=>$i['harga']*$i['jumlah']); $pengiriman=Pengiriman::where('aktif',true)->get(); return view('user.checkout',compact('keranjang','total','pengiriman')); }
 public function proses(Request $r){ if(!auth()->check()) return redirect('/login'); $k=$r->session()->get('keranjang',[]); if(empty($k)) return redirect('/keranjang'); $d=$r->validate(['nama'=>'required|max:100','no_hp'=>'required|max:20','alamat'=>'required','pengiriman_id'=>'required|exists:pengiriman,id','metode'=>'required']); $trx=DB::transaction(function() use($r,$k,$d){ $ship=Pengiriman::findOrFail($d['pengiriman_id']); $subtotal=collect($k)->sum(fn($i)=>$i['harga']*$i['jumlah']); $total=$subtotal+$ship->biaya; $trx=Transaksi::create(['user_id'=>auth()->id(),'nama_penerima'=>$d['nama'],'total'=>$total,'biaya_pengiriman'=>$ship->biaya,'alamat'=>$d['alamat'],'no_hp'=>$d['no_hp'],'metode_pengiriman'=>$ship->nama_metode,'status'=>'Menunggu','tanggal'=>now()]); foreach($k as $id=>$item){ $stok=Stok::where('produk_id',$id)->lockForUpdate()->first(); if(!$stok || $stok->jumlah<$item['jumlah']) throw new \RuntimeException('Stok produk berubah. Silakan ulangi checkout.'); $stok->jumlah-=$item['jumlah']; $stok->save(); DetailTransaksi::create(['transaksi_id'=>$trx->id,'produk_id'=>$id,'jumlah'=>$item['jumlah'],'harga'=>$item['harga'],'subtotal'=>$item['harga']*$item['jumlah']]); } $trx->pembayaran()->create(['metode'=>$d['metode'],'jumlah'=>$total,'status'=>'Menunggu','tanggal'=>now()]); return $trx; }); $r->session()->forget('keranjang'); return redirect('/pembayaran/'.$trx->id); }
}
